'use client';

import { useAuth } from '@/context/AuthContext';
import { useRouter, usePathname } from 'next/navigation';
import { useEffect, ReactNode } from 'react';
import Link from 'next/link';
import {
    LayoutDashboard, Users, Building2, BookOpen, ClipboardCheck,
    FileCheck, BarChart3, GraduationCap, CalendarCheck, LogOut,
    ChevronRight, Workflow, FileText, Layers, DoorOpen,
    Upload, Clock, Calendar
} from 'lucide-react';

const ROLE_NAV: Record<string, { label: string; href: string; icon: ReactNode }[]> = {
    super_admin: [
        { label: 'Dashboard', href: '/dashboard', icon: <LayoutDashboard size={18} /> },
        { label: 'Institutions', href: '/dashboard/tenants', icon: <Building2 size={18} /> },
        { label: 'All Users', href: '/dashboard/users', icon: <Users size={18} /> },
    ],
    admin: [
        { label: 'Dashboard', href: '/dashboard', icon: <LayoutDashboard size={18} /> },
        { label: 'Users', href: '/dashboard/users', icon: <Users size={18} /> },
        { label: 'Departments', href: '/dashboard/departments', icon: <Building2 size={18} /> },
        { label: 'Programs', href: '/dashboard/programs', icon: <BookOpen size={18} /> },
        { label: 'Subjects', href: '/dashboard/subjects', icon: <FileText size={18} /> },
        { label: 'Batches', href: '/dashboard/batches', icon: <Layers size={18} /> },
        { label: 'Classrooms', href: '/dashboard/classrooms', icon: <DoorOpen size={18} /> },
        { label: 'Bulk Import', href: '/dashboard/bulk-import', icon: <Upload size={18} /> },
        { label: 'Faculty Workload', href: '/dashboard/faculty-workload', icon: <Clock size={18} /> },
        { label: 'Timetable', href: '/dashboard/timetable', icon: <Calendar size={18} /> },
        { label: 'Marks Lock', href: '/dashboard/marks-lock', icon: <ClipboardCheck size={18} /> },
        { label: 'Compliance', href: '/dashboard/compliance', icon: <FileCheck size={18} /> },
    ],
    hod: [
        { label: 'Dashboard', href: '/dashboard', icon: <LayoutDashboard size={18} /> },
        { label: 'Mark Approvals', href: '/dashboard/marks-approval', icon: <ClipboardCheck size={18} /> },
        { label: 'OD Approvals', href: '/dashboard/od-approval', icon: <Workflow size={18} /> },
        { label: 'Department Stats', href: '/dashboard/dept-stats', icon: <BarChart3 size={18} /> },
    ],
    faculty: [
        { label: 'Dashboard', href: '/dashboard', icon: <LayoutDashboard size={18} /> },
        { label: 'Attendance', href: '/dashboard/attendance', icon: <CalendarCheck size={18} /> },
        { label: 'Marks Entry', href: '/dashboard/marks-entry', icon: <ClipboardCheck size={18} /> },
        { label: 'OD Requests', href: '/dashboard/od-requests', icon: <Workflow size={18} /> },
        { label: 'My Timetable', href: '/dashboard/timetable', icon: <Calendar size={18} /> },
    ],
    student: [
        { label: 'Dashboard', href: '/dashboard', icon: <LayoutDashboard size={18} /> },
        { label: 'My Attendance', href: '/dashboard/my-attendance', icon: <CalendarCheck size={18} /> },
        { label: 'My Marks', href: '/dashboard/my-marks', icon: <GraduationCap size={18} /> },
        { label: 'Apply OD', href: '/dashboard/apply-od', icon: <Workflow size={18} /> },
        { label: 'My Timetable', href: '/dashboard/timetable', icon: <Calendar size={18} /> },
    ],
};

const ROLE_COLORS: Record<string, string> = {
    super_admin: '#7c3aed',
    admin: '#2563eb',
    hod: '#0891b2',
    faculty: '#059669',
    student: '#d97706',
};

const ROLE_LABELS: Record<string, string> = {
    super_admin: 'Super Admin',
    admin: 'Institution Admin',
    hod: 'Head of Department',
    faculty: 'Faculty',
    student: 'Student',
};

export default function DashboardLayout({ children }: { children: ReactNode }) {
    const { user, loading, logout, isAuthenticated } = useAuth();
    const router = useRouter();
    const pathname = usePathname();

    useEffect(() => {
        if (!loading && !isAuthenticated) {
            router.push('/login');
        }
    }, [loading, isAuthenticated, router]);

    if (loading || !user) {
        return (
            <div style={{
                minHeight: '100vh', display: 'flex', alignItems: 'center',
                justifyContent: 'center', background: '#F5F7F9',
            }}>
                <div style={{ textAlign: 'center' }}>
                    <div style={{
                        width: 44, height: 44, borderRadius: 10,
                        background: 'linear-gradient(135deg, #142B34, #1F3F4A)',
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        color: 'white', fontWeight: 800, fontSize: 20, fontFamily: 'Poppins',
                        margin: '0 auto 12px',
                    }}>E</div>
                    <p style={{ color: '#5a6a72', fontSize: 14 }}>Loading...</p>
                </div>
            </div>
        );
    }

    const navItems = ROLE_NAV[user.role] || [];
    const roleColor = ROLE_COLORS[user.role] || '#142B34';

    return (
        <div style={{ display: 'flex', minHeight: '100vh', background: '#F5F7F9' }}>
            {/* Sidebar */}
            <aside style={{
                width: 260, background: '#142B34', color: 'white',
                display: 'flex', flexDirection: 'column', flexShrink: 0,
                position: 'fixed', top: 0, left: 0, bottom: 0, zIndex: 50,
            }}>
                {/* Logo */}
                <div style={{
                    padding: '20px 24px', borderBottom: '1px solid rgba(255,255,255,0.08)',
                    display: 'flex', alignItems: 'center', gap: 10,
                }}>
                    <div style={{
                        width: 34, height: 34, borderRadius: 8,
                        background: 'rgba(255,255,255,0.1)', display: 'flex',
                        alignItems: 'center', justifyContent: 'center',
                        fontWeight: 800, fontSize: 16, fontFamily: 'Poppins',
                    }}>E</div>
                    <span style={{ fontSize: 18, fontWeight: 700, fontFamily: 'Poppins' }}>EduNexis</span>
                </div>

                {/* Nav */}
                <nav style={{ flex: 1, padding: '16px 12px', display: 'flex', flexDirection: 'column', gap: 4 }}>
                    {navItems.map((item) => {
                        const isActive = pathname === item.href;
                        return (
                            <Link
                                key={item.href}
                                href={item.href}
                                style={{
                                    display: 'flex', alignItems: 'center', gap: 12,
                                    padding: '10px 14px', borderRadius: 8,
                                    fontSize: 14, fontWeight: isActive ? 600 : 400,
                                    color: isActive ? 'white' : 'rgba(255,255,255,0.6)',
                                    background: isActive ? 'rgba(255,255,255,0.1)' : 'transparent',
                                    textDecoration: 'none', transition: 'all 0.2s',
                                }}
                            >
                                {item.icon}
                                {item.label}
                                {isActive && (
                                    <ChevronRight size={14} style={{ marginLeft: 'auto', opacity: 0.5 }} />
                                )}
                            </Link>
                        );
                    })}
                </nav>

                {/* User card */}
                <div style={{
                    padding: '16px 16px 20px', borderTop: '1px solid rgba(255,255,255,0.08)',
                }}>
                    <div style={{
                        display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12,
                    }}>
                        <div style={{
                            width: 36, height: 36, borderRadius: 8,
                            background: roleColor, display: 'flex',
                            alignItems: 'center', justifyContent: 'center',
                            fontWeight: 700, fontSize: 14,
                        }}>
                            {user.name.charAt(0)}
                        </div>
                        <div style={{ flex: 1, minWidth: 0 }}>
                            <div style={{ fontSize: 13, fontWeight: 600, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                                {user.name}
                            </div>
                            <div style={{ fontSize: 11, opacity: 0.5 }}>{ROLE_LABELS[user.role]}</div>
                        </div>
                    </div>
                    <button
                        onClick={() => { logout(); router.push('/login'); }}
                        style={{
                            width: '100%', padding: '8px 0', borderRadius: 6,
                            border: '1px solid rgba(255,255,255,0.15)', background: 'transparent',
                            color: 'rgba(255,255,255,0.6)', fontSize: 13, fontWeight: 500,
                            cursor: 'pointer', display: 'flex', alignItems: 'center',
                            justifyContent: 'center', gap: 6, transition: 'all 0.2s',
                        }}
                    >
                        <LogOut size={14} /> Sign Out
                    </button>
                </div>
            </aside>

            {/* Main content */}
            <main style={{ flex: 1, marginLeft: 260 }}>
                {/* Top bar */}
                <header style={{
                    height: 60, background: 'white', borderBottom: '1px solid #e2e6ea',
                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    padding: '0 32px', position: 'sticky', top: 0, zIndex: 40,
                }}>
                    <div style={{ fontSize: 14, color: '#5a6a72' }}>
                        {user.tenant_id ? (
                            <span>
                                Tenant: <strong style={{ color: '#142B34' }}>{user.tenant_id}</strong>
                            </span>
                        ) : (
                            <span style={{ color: '#142B34', fontWeight: 600 }}>Platform Administration</span>
                        )}
                    </div>
                    <div style={{
                        fontSize: 11, fontWeight: 600, padding: '4px 10px',
                        borderRadius: 4, background: `${roleColor}15`, color: roleColor,
                        textTransform: 'uppercase', letterSpacing: 0.5,
                    }}>
                        {ROLE_LABELS[user.role]}
                    </div>
                </header>

                {/* Page content */}
                <div style={{ padding: 32 }}>
                    {children}
                </div>
            </main>
        </div>
    );
}
